function somaValor(items) {
  return items.reduce(function(sum, i) {
    return sum + parseFloat(i.json.valor || 0);
  }, 0);
}

function agrupar(items, campo) {
  const grupo = {};
  items.forEach(function(i) {
    const chave = i.json[campo] || 'N/A';
    grupo[chave] = (grupo[chave] || 0) + parseFloat(i.json.valor || 0);
  });
  const entries = Object.entries(grupo).sort(function(a, b) { return b[1] - a[1]; });
  let rows = '';
  entries.forEach(function(entry) {
    rows += '<tr><td>' + entry[0] + '</td><td>R$ ' + entry[1].toFixed(2) + '</td></tr>';
  });
  return rows;
}

